            className,
          )}
          {...props}
        >
          {/* Full-bleed background image - spans 100% width and height of outer container, completely unwrapped */}
          <LiquidGlassSvgFilter id={filterId} bgImage={liquidBg} />
          <img
            src={liquidBg}
            alt=""
