  hoverLabel = "share",
  signUps,
  showCodes = true,
  title,
  caption,
  metrics,
}: ChartBlockProps) {
  const themeColor = getThemeColor(color);
  const isSelfSizing =
    type === "donut-legend" ||
    type === "stacked-bar" ||
    type === "traffic-sources" ||
    type === "visitors-by-country" ||
    type === "metrics-overview";

  // Every share gets a colour: its own, else the palette in order, wrapping.
  const shareColor = (d: ChartDataPoint, i: number) =>
    getThemeColor(d.color ?? colors[i % colors.length] ?? "primary");

  if (type === "metrics-overview") {
    const activeMetrics =
      metrics ||
      (data && data.length > 0
        ? [
            {
              id: "metric-1",
              label: title || "Overview",
              points: data.map((d) => ({
                label: d.label,
                value: d.value,
              })),
            },
          ]
        : undefined);

    return (
      <MetricsOverviewChart
        metrics={activeMetrics}
        title={title}
        compareCaption={caption}
        className={className}
      />
    );
  }

  if (type === "traffic-sources") {
    return (
      <TrafficSourcesChart
        data={data}
        colors={colors}
        signUps={signUps}
        title={title}
        caption={caption}
        className={className}
      />
    );
  }

  if (type === "visitors-by-country") {
    return (
      <VisitorsByCountryChart
        data={data}
        colors={colors}
        showCodes={showCodes}
        title={title}
        caption={caption}
        className={className}
      />
    );
  }

  return (
    <div
      className={cn("relative w-full", className)}
      style={{ height: height ?? (isSelfSizing ? undefined : 300) }}
    >
      {/* NATIVE CSS ANIMATIONS */}
      <style>{`
        @keyframes drawLine { from { clip-path: inset(-8px 100% -8px -8px); } to { clip-path: inset(-8px -8px -8px -8px); } }
        @keyframes growUp { from { transform: scaleY(0); opacity: 0; } to { transform: scaleY(1); opacity: 1; } }
        @keyframes fadeUp { from { transform: translateY(10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-draw { animation: drawLine 1.5s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-grow { animation: growUp 1s cubic-bezier(0.22, 1, 0.36, 1) forwards; transform-origin: bottom; }
        .animate-fade { animation: fadeUp 1s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
      `}</style>

      {type === "bar" && (
        <BarChart
          data={data}
          color={themeColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
          showGrid={showGrid}
        />
      )}

      {type === "line" && (
        <SmoothLineChart
          data={data}
          color={themeColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
          showGrid={showGrid}
          showArea={showArea}
        />
      )}

      {(type === "pie" || type === "donut") && (
        <CircularChart
          data={data}
          type={type}
          color={themeColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
        />
      )}

      {type === "donut-legend" && (
        <DonutLegendChart
          data={data}
          shareColor={shareColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
          centerLabel={centerLabel}
          hoverLabel={hoverLabel}
        />
      )}

      {type === "stacked-bar" && (
        <StackedBarChart
          data={data}
          shareColor={shareColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
        />
      )}
    </div>
  );
}

